function finalPrice(order: any) {
  if (order.customer === 'VIP') return order.amount * 0.8;
  if (order.amount > 1000 && order.region === 'EU') return order.amount * 0.9;
  if (order.coupon) return order.amount - order.coupon.value;
  return order.amount;
}

// Version A
function charge(order: any) {
  switch (order.type) {
    case 'PREMIUM':
      return order.base * 0.9 + 20;
    case 'STANDARD':
      if (order.weight > 10) return order.base + order.weight * 2;
      return order.base + 5;
    default:
      return order.base;
  }
}

// Version B
function chargePremium(order: any) { return order.base * 0.9 + 20; }
function chargeStandard(order: any) { return order.weight > 10 ? order.base + order.weight * 2 : order.base + 5; }
function charge(order: any) { const map: any = { PREMIUM: chargePremium, STANDARD: chargeStandard }; return (map[order.type] || (() => order.base))(order); }
